function kthSmallest(nums, k) {
  const a = [...nums]; let lo = 0, hi = a.length - 1 //@init
  while (true) {
    const mid = (lo + hi) >> 1; [a[mid], a[hi]] = [a[hi], a[mid]] //@pivot
    const pivot = a[hi]; let store = lo
    for (let j = lo; j < hi; j++) {
      if (a[j] < pivot) { //@scan
        [a[store], a[j]] = [a[j], a[store]]; store++ //@swap
      }
    }
    [a[store], a[hi]] = [a[hi], a[store]] //@place
    if (store === k - 1) return a[store] //@found
    if (store < k - 1) lo = store + 1 //@right
    else hi = store - 1 //@left
  }
}

