def partition(a, lo, hi):
    mid = (lo + hi) // 2
    a[mid], a[hi] = a[hi], a[mid]  # middle pivot, moved to the end
    pivot, store = a[hi], lo
    for j in range(lo, hi):
        if a[j] < pivot:  # smaller values go left of store
            a[store], a[j] = a[j], a[store]
            store += 1
    a[store], a[hi] = a[hi], a[store]  # pivot lands in its sorted place
    return store

def select(a, k):  # k-th smallest, 1-based
    lo, hi = 0, len(a) - 1
    while True:
        p = partition(a, lo, hi)
        if p == k - 1:
            return a[p]
        if p < k - 1:
            lo = p + 1  # answer is right of the pivot
        else:
            hi = p - 1  # answer is left of the pivot

